Read the risk rows from the active sheet and group Risk IDs by their integer Impact and Likelihood values. Map the 3×3 answer block F12:H14 with rows Impact 3→1 and columns Likelihood 1→3. Write comma-separated ID lists, or leave empty boxes as `None`.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def clean_id(value):
    if value is None:
        return None
    if isinstance(value, float) and value.is_integer():
        return str(int(value))
    s = str(value).strip()
    return s if s else None

# Locate data columns from the header row if possible
header = {}
for col in range(1, vws.max_column + 1):
    v = vws.cell(row=3, column=col).value
    if v is not None:
        header[str(v).strip().lower()] = col

id_col = header.get("id", 1)
impact_col = header.get("impact", 2)
likelihood_col = header.get("liklihood", header.get("likelihood", 3))

groups = {}

for row in range(4, vws.max_row + 1):
    rid = clean_id(vws.cell(row=row, column=id_col).value)
    if rid is None:
        continue

    impact_raw = vws.cell(row=row, column=impact_col).value
    likelihood_raw = vws.cell(row=row, column=likelihood_col).value

    try:
        impact = int(float(impact_raw))
        likelihood = int(float(likelihood_raw))
    except (TypeError, ValueError):
        continue

    if 1 <= impact <= 3 and 1 <= likelihood <= 3:
        groups.setdefault((impact, likelihood), []).append(rid)

# Fill F12:H14:
# rows 12,13,14 correspond to Impact 3,2,1
# columns F,G,H correspond to Likelihood 1,2,3
for r in range(12, 15):
    impact = 15 - r
    for c in range(6, 9):
        likelihood = c - 5
        ids = groups.get((impact, likelihood), [])
        ws.cell(row=r, column=c).value = ", ".join(ids) if ids else None

print("Groups:", groups)
for r in range(12, 15):
    print([ws.cell(row=r, column=c).value for c in range(6, 9)])

wb.save(OUT)
```

